let wasos_config = {
    username: msg.config.username,
    user_id: msg.payload.profileId,
    chatroom_name: msg.config.chatroom_name,
    api: {
        key: msg.payload.nonce,
        expires: msg.payload.refresh_expires
    },
    group: msg.payload.groups,
}

global.set("wasos_config", wasos_config)

msg.payload = wasos_config
return msg;

if (
    msg.payload.wasos_username.length > 0 && 
    msg.payload.wasos_password.length > 0 &&
    msg.payload.wasos_chatroom_name.length > 0
    ) 
    {
        return msg;
    } else {
        node.error("missing wasos config in msg.payload: ", msg);
        return null
    }

let config = global.get("wasos_config");
msg.topic = "wasos_configured"

if (config.chatroom_name &&
    config.api.key) {
        msg.payload = true;
        return msg;
    } else {
        node.error("wasos config not correctly configured", global.get("wasos_config"));
        return null;
    }
